`timescale 1ns/1ps

// Cross-integration test: bytes are generated by the unmodified STM32
// fpga_link.c host build and loaded through +FRAME_HEX. SPI is replayed at
// nominal 500 kHz, Mode 0, MSB first.
module tb_stm32_fpga_cross;
    reg clk = 0;
    reg rst = 1;
    reg spi_sck = 0;
    reg spi_mosi = 0;
    reg spi_cs_n = 1;
    reg buffer_sample_valid = 0;
    reg [7:0] buffer_sample_data = 0;
    reg filter_sample_valid = 0;
    reg [7:0] filter_sample_in = 8'd128;
    reg [7:0] test_phase = 0;
    reg [15:0] notch_frequency = 0;

    wire spi_miso;
    wire [7:0] dsp_mode;
    wire coeff_update_valid;
    wire [7:0] coeff_update_seq;
    wire signed [15:0] coeff_b0, coeff_b1, coeff_b2, coeff_a1, coeff_a2;
    wire filter_coeff_valid, filter_coeff_applied, filter_sample_out_valid;
    wire [7:0] filter_applied_seq, filter_sample_out;
    wire overflow, block_valid, block_bank, block_read_bank;
    wire [15:0] block_id;
    wire [8:0] block_read_addr;
    wire [7:0] block_read_data;
    wire block_consume_valid, block_consume_bank, clear_overflow;
    wire [1:0] ready_debug;

    reg [7:0] frames [0:536];
    reg [7:0] block_rx [0:514];
    reg [7:0] rx, state_mode, state_seq, state_flags, block_status;
    reg [7:0] expected_crc, observed_crc;
    reg signed [15:0] saved_b0, saved_b1, saved_b2, saved_a1, saved_a2;
    reg [7:0] saved_seq;
    integer i;
    integer update_count = 0;
    integer byte_log;
    integer pass_count = 0;
    integer sample_value;
    integer n;
    real pi;
    real sum_cos, sum_sin, amplitude, attenuation_db;
    reg [2047:0] frame_hex_path;
    reg [2047:0] vcd_path;
    reg [2047:0] byte_log_path;

    always #10 clk = ~clk;

    analysis_buffer_512 buffer (
        .clk(clk), .rst(rst), .sample_valid(buffer_sample_valid),
        .sample_data(buffer_sample_data), .clear_overflow(clear_overflow),
        .overflow_sticky(overflow), .selected_valid(block_valid),
        .selected_bank(block_bank), .selected_id(block_id),
        .read_bank(block_read_bank), .read_addr(block_read_addr),
        .read_data(block_read_data), .consume_valid(block_consume_valid),
        .consume_bank(block_consume_bank), .ready_debug(ready_debug)
    );

    spi_mode0_slave_w2 spi (
        .clk(clk), .rst(rst), .spi_sck(spi_sck), .spi_mosi(spi_mosi),
        .spi_cs_n(spi_cs_n), .spi_miso(spi_miso), .dsp_mode(dsp_mode),
        .coeff_update_valid(coeff_update_valid), .coeff_update_seq(coeff_update_seq),
        .coeff_b0(coeff_b0), .coeff_b1(coeff_b1), .coeff_b2(coeff_b2),
        .coeff_a1(coeff_a1), .coeff_a2(coeff_a2),
        .auto_coeff_valid(filter_coeff_valid), .applied_coeff_seq(filter_applied_seq),
        .block_valid(block_valid), .block_bank(block_bank), .block_id(block_id),
        .block_overflow(overflow), .block_read_bank(block_read_bank),
        .block_read_addr(block_read_addr), .block_read_data(block_read_data),
        .block_consume_valid(block_consume_valid),
        .block_consume_bank(block_consume_bank), .clear_overflow(clear_overflow)
    );

    iir_notch_variable filter (
        .clk(clk), .rst(rst), .sample_valid(filter_sample_valid),
        .sample_in(filter_sample_in), .coeff_update_valid(coeff_update_valid),
        .coeff_update_seq(coeff_update_seq), .coeff_b0(coeff_b0),
        .coeff_b1(coeff_b1), .coeff_b2(coeff_b2), .coeff_a1(coeff_a1),
        .coeff_a2(coeff_a2), .coeff_valid(filter_coeff_valid),
        .applied_seq(filter_applied_seq), .coeff_applied(filter_coeff_applied),
        .sample_out_valid(filter_sample_out_valid), .sample_out(filter_sample_out)
    );

    always @(posedge clk) begin
        if (coeff_update_valid)
            update_count = update_count + 1;
    end

    function automatic [7:0] crc8;
        input [7:0] crc_in;
        input [7:0] data;
        integer bit_index;
        reg [7:0] value;
        begin
            value = crc_in ^ data;
            for (bit_index = 0; bit_index < 8; bit_index = bit_index + 1)
                value = value[7] ? ((value << 1) ^ 8'h07) : (value << 1);
            crc8 = value;
        end
    endfunction

    function automatic [7:0] pattern;
        input integer index;
        begin
            pattern = (index * 37 + 13) & 8'hff;
        end
    endfunction

    task automatic spi_byte;
        input [7:0] tx;
        output [7:0] data_rx;
        integer bit_index;
        begin
            data_rx = 0;
            for (bit_index = 7; bit_index >= 0; bit_index = bit_index - 1) begin
                spi_mosi = tx[bit_index];
                #1000;
                spi_sck = 1;
                #100;
                data_rx[bit_index] = spi_miso;
                #900;
                spi_sck = 0;
            end
            $fwrite(byte_log, "%0t phase=%0d TX=%02X RX=%02X\n", $time, test_phase, tx, data_rx);
        end
    endtask

    task automatic begin_frame;
        begin
            spi_sck = 0;
            spi_cs_n = 0;
            #1000;
        end
    endtask

    task automatic end_frame;
        begin
            #1000;
            spi_cs_n = 1;
            spi_mosi = 0;
            #1000;
        end
    endtask

    task automatic send_mode;
        input integer frame_index;
        input [7:0] expected_mode;
        begin
            begin_frame;
            spi_byte(frames[frame_index], rx);
            end_frame;
            if (dsp_mode !== expected_mode)
                $fatal(1, "FAIL MODE frame=%02X observed=%02X expected=%02X", frames[frame_index], dsp_mode, expected_mode);
        end
    endtask

    task automatic read_state;
        begin
            begin_frame;
            spi_byte(frames[3], rx);
            spi_byte(frames[4], state_mode);
            spi_byte(frames[5], state_seq);
            spi_byte(frames[6], state_flags);
            end_frame;
            $display("OBSERVED READ_STATE TX=21 00 00 00 RX=xx %02X %02X %02X", state_mode, state_seq, state_flags);
        end
    endtask

    task automatic measure_tone;
        input integer frequency;
        input integer warmup_count;
        input integer measure_count;
        output real db;
        begin
            notch_frequency = frequency;
            sum_cos = 0.0;
            sum_sin = 0.0;
            for (n = 0; n < warmup_count + measure_count; n = n + 1) begin
                @(negedge clk);
                sample_value = $rtoi(128.0 + 40.0 * $sin(2.0 * pi * frequency * n / 16000.0));
                filter_sample_in = sample_value[7:0];
                filter_sample_valid = 1;
                @(posedge clk);
                #1;
                if (!filter_sample_out_valid)
                    $fatal(1, "FAIL NOTCH missing output frequency=%0d sample=%0d", frequency, n);
                if (n >= warmup_count) begin
                    sum_cos = sum_cos + ($itor(filter_sample_out) - 128.0) *
                              $cos(2.0 * pi * frequency * n / 16000.0);
                    sum_sin = sum_sin + ($itor(filter_sample_out) - 128.0) *
                              $sin(2.0 * pi * frequency * n / 16000.0);
                end
            end
            @(negedge clk);
            filter_sample_valid = 0;
            amplitude = 2.0 * $sqrt(sum_cos * sum_cos + sum_sin * sum_sin) / measure_count;
            if (amplitude < 0.0001)
                db = -120.0;
            else
                db = 20.0 * $ln(amplitude / 40.0) / $ln(10.0);
            $display("METRIC NOTCH frequency=%0dHz output_amplitude=%0.4f gain_db=%0.3f", frequency, amplitude, db);
        end
    endtask

    initial begin
        if (!$value$plusargs("FRAME_HEX=%s", frame_hex_path))
            $fatal(1, "FAIL missing +FRAME_HEX");
        if (!$value$plusargs("VCD=%s", vcd_path))
            $fatal(1, "FAIL missing +VCD");
        if (!$value$plusargs("BYTE_LOG=%s", byte_log_path))
            $fatal(1, "FAIL missing +BYTE_LOG");
        $readmemh(frame_hex_path, frames);
        byte_log = $fopen(byte_log_path, "w");
        if (!byte_log)
            $fatal(1, "FAIL cannot open byte log");
        $dumpfile(vcd_path);
        $dumpvars(0, test_phase, spi_cs_n, spi_sck, spi_mosi, spi_miso);
        $dumpvars(0, dsp_mode, coeff_update_valid, coeff_update_seq);
        $dumpvars(0, filter_coeff_valid, filter_coeff_applied, filter_applied_seq);
        $dumpvars(0, filter_sample_valid, filter_sample_in, filter_sample_out_valid, filter_sample_out);
        $dumpvars(0, notch_frequency);
        $dumpvars(0, block_valid, block_id, block_consume_valid, ready_debug);
        $dumpvars(0, filter.active_b0, filter.active_b1, filter.active_b2, filter.active_a1, filter.active_a2);

        pi = 3.14159265358979323846;
        repeat (5) @(posedge clk);
        rst = 0;
        #200;

        test_phase = 1;
        send_mode(0, 8'h02);
        pass_count = pass_count + 1;
        $display("PASS 1 FIXED STM32_TX=%02X FPGA_MODE=%02X", frames[0], dsp_mode);

        test_phase = 2;
        read_state;
        if (state_mode !== 8'h02 || state_seq !== 8'hff || state_flags !== 8'h00)
            $fatal(1, "FAIL 2 READ_STATE mode=%02X seq=%02X flags=%02X", state_mode, state_seq, state_flags);
        pass_count = pass_count + 1;
        $display("PASS 2 READ_STATE mode=%02X seq=%02X flags=%02X", state_mode, state_seq, state_flags);

        test_phase = 3;
        send_mode(1, 8'h01);
        send_mode(2, 8'h06);
        send_mode(0, 8'h02);
        pass_count = pass_count + 1;
        $display("PASS 3 BYPASS/AUTO/FIXED TX=%02X/%02X/%02X final=%02X", frames[1], frames[2], frames[0], dsp_mode);

        for (i = 0; i < 512; i = i + 1) begin
            @(negedge clk);
            buffer_sample_data = pattern(i);
            buffer_sample_valid = 1;
        end
        @(negedge clk);
        buffer_sample_valid = 0;
        @(posedge clk);
        #1;
        if (!block_valid || block_id !== 16'h0000)
            $fatal(1, "FAIL 4 buffer block_valid=%b id=%04X", block_valid, block_id);

        test_phase = 4;
        begin_frame;
        spi_byte(frames[7], rx);
        spi_byte(frames[8], block_status);
        #10000; // same CS Low, but a deliberate gap between STM32 transfer calls
        for (i = 0; i < 515; i = i + 1)
            spi_byte(frames[9 + i], block_rx[i]);
        end_frame;
        if (block_status !== 8'h01)
            $fatal(1, "FAIL 4 READ_BLOCK status=%02X", block_status);
        if ({block_rx[1], block_rx[0]} !== 16'h0000)
            $fatal(1, "FAIL 4 READ_BLOCK id=%02X%02X", block_rx[1], block_rx[0]);
        expected_crc = 0;
        expected_crc = crc8(expected_crc, block_rx[0]);
        expected_crc = crc8(expected_crc, block_rx[1]);
        for (i = 0; i < 512; i = i + 1) begin
            if (block_rx[2 + i] !== pattern(i))
                $fatal(1, "FAIL 4 READ_BLOCK sample=%0d observed=%02X expected=%02X", i, block_rx[2 + i], pattern(i));
            expected_crc = crc8(expected_crc, block_rx[2 + i]);
        end
        observed_crc = block_rx[514];
        #200;
        if (observed_crc !== expected_crc || block_valid)
            $fatal(1, "FAIL 4 READ_BLOCK crc=%02X/%02X consumed=%b", observed_crc, expected_crc, !block_valid);
        pass_count = pass_count + 1;
        $display("PASS 4 READ_BLOCK status=%02X id=%02X%02X samples=512 first=%02X last=%02X crc=%02X split_gap=10us",
                 block_status, block_rx[1], block_rx[0], block_rx[2], block_rx[513], observed_crc);

        test_phase = 5;
        i = update_count;
        begin_frame;
        for (i = 524; i <= 536; i = i + 1)
            spi_byte(frames[i], rx);
        end_frame;
        if (update_count != 1)
            $fatal(1, "FAIL 5 SET_COEFF update pulse count=%0d", update_count);
        if (filter_coeff_valid)
            $fatal(1, "FAIL 5 SET_COEFF applied before sample boundary");
        if (coeff_update_seq !== 8'h01 || coeff_b0 !== 16'sd16384 || coeff_b1 !== -16'sd30274 ||
            coeff_b2 !== 16'sd16384 || coeff_a1 !== -16'sd29668 || coeff_a2 !== 16'sd15735)
            $fatal(1, "FAIL 5 SET_COEFF decoded seq=%02X coeff=%0d,%0d,%0d,%0d,%0d",
                   coeff_update_seq, coeff_b0, coeff_b1, coeff_b2, coeff_a1, coeff_a2);
        @(negedge clk);
        filter_sample_in = 8'd128;
        filter_sample_valid = 1;
        @(posedge clk);
        #1;
        if (!filter_coeff_applied || !filter_coeff_valid || filter_applied_seq !== 8'h01)
            $fatal(1, "FAIL 5 atomic apply applied=%b valid=%b seq=%02X", filter_coeff_applied, filter_coeff_valid, filter_applied_seq);
        if (filter.active_b0 !== 16'sd16384 || filter.active_b1 !== -16'sd30274 ||
            filter.active_b2 !== 16'sd16384 || filter.active_a1 !== -16'sd29668 ||
            filter.active_a2 !== 16'sd15735)
            $fatal(1, "FAIL 5 active coefficients are not atomic");
        @(negedge clk);
        filter_sample_valid = 0;
        pass_count = pass_count + 1;
        $display("PASS 5 SET_COEFF frame=20 01 00 40 BE 89 00 40 1C 8C 77 3D 62 atomic_seq=%02X", filter_applied_seq);

        test_phase = 6;
        read_state;
        if (state_mode !== 8'h02 || state_seq !== 8'h01 || state_flags !== 8'h01)
            $fatal(1, "FAIL 6 READ_STATE applied mode=%02X seq=%02X flags=%02X", state_mode, state_seq, state_flags);
        pass_count = pass_count + 1;
        $display("PASS 6 APPLIED_SEQ READ_STATE mode=%02X seq=%02X flags=%02X", state_mode, state_seq, state_flags);

        test_phase = 7;
        saved_b0 = filter.active_b0;
        saved_b1 = filter.active_b1;
        saved_b2 = filter.active_b2;
        saved_a1 = filter.active_a1;
        saved_a2 = filter.active_a2;
        saved_seq = filter_applied_seq;
        i = update_count;
        begin_frame;
        for (n = 524; n <= 535; n = n + 1)
            spi_byte(frames[n], rx);
        end_frame;
        begin_frame;
        for (n = 524; n <= 535; n = n + 1)
            spi_byte(frames[n], rx);
        spi_byte(frames[536] ^ 8'h01, rx);
        end_frame;
        #300;
        if (update_count != i || dsp_mode !== 8'h02 || filter_applied_seq !== saved_seq ||
            filter.active_b0 !== saved_b0 || filter.active_b1 !== saved_b1 ||
            filter.active_b2 !== saved_b2 || filter.active_a1 !== saved_a1 || filter.active_a2 !== saved_a2)
            $fatal(1, "FAIL 7 invalid SET_COEFF changed state updates=%0d/%0d mode=%02X seq=%02X", update_count, i, dsp_mode, filter_applied_seq);
        pass_count = pass_count + 1;
        $display("PASS 7 INCOMPLETE/BAD_CRC preserved mode=%02X seq=%02X coefficients", dsp_mode, filter_applied_seq);

        test_phase = 8;
        measure_tone(1000, 512, 4096, attenuation_db);
        if (attenuation_db > -10.0)
            $fatal(1, "FAIL 8 NOTCH 1000Hz attenuation=%0.3fdB", attenuation_db);
        $display("PASS 8A STM32_R098 1000Hz attenuation=%0.3fdB", attenuation_db);
        measure_tone(500, 512, 4096, attenuation_db);
        if (attenuation_db > 1.0 || attenuation_db < -1.0)
            $fatal(1, "FAIL 8 NOTCH 500Hz gain=%0.3fdB", attenuation_db);
        pass_count = pass_count + 1;
        $display("PASS 8B STM32_R098 500Hz gain=%0.3fdB", attenuation_db);

        test_phase = 9;
        $display("PASS CROSS_INTEGRATION tests=%0d source=STM32_C_HOST_NOT_PHYSICAL_BOARD", pass_count);
        $fclose(byte_log);
        $finish;
    end

    initial begin
        #30000000;
        $fatal(1, "FAIL CROSS_INTEGRATION timeout");
    end
endmodule
